async function getUser(id) {
  const key = `user:${id}`;
  const cached = await redis.get(key);
  if (cached) return JSON.parse(cached); // hit
  const user = await db.users.findById(id); // miss -> source of truth
  await redis.set(key, JSON.stringify(user), { EX: 600 }); // TTL 10 min
  return user;
}

async function updateUser(id, changes) {
  await db.users.update(id, changes); // 1. write the database
  await redis.del(`user:${id}`); // 2. invalidate the cache
}

async function withRetry(fn, { retries = 3, baseMs = 100, maxMs = 2000 } = {}) {
  for (let attempt = 0; ; attempt++) {
    try {
      return await fn();
    } catch (err) {
      if (attempt >= retries) throw err; // give up: surface the error
      const cap = Math.min(maxMs, baseMs * 2 ** attempt);
      const delay = Math.random() * cap; // "full jitter" spreads retries out
      await new Promise((resolve) => setTimeout(resolve, delay));
    }
  }
}

