class LoadBalancer {
  constructor(names) {
    this.servers = names.map((name) => ({ name, healthy: true, active: 0 }));
    this.cursor = 0; // round-robin position
  }

  pool() {
    return this.servers.filter((s) => s.healthy); // only healthy servers get traffic
  }

  pickRoundRobin() {
    const pool = this.pool();
    return pool[this.cursor++ % pool.length];
  }

  pickLeastConnections() {
    return this.pool().reduce((best, s) => (s.active < best.active ? s : best));
  }

  route(request) {
    if (this.pool().length === 0) throw new Error('503: no healthy server');
    const server = this.pickLeastConnections();
    server.active++; // connection opened
    request.onFinish(() => server.active--); // connection closed
    return server.name;
  }

  onHealthCheck(name, ok) {
    this.servers.find((s) => s.name === name).healthy = ok;
  }
}

class LRUCache {
  constructor(capacity) {
    this.capacity = capacity;
    this.map = new Map(); // Map keeps insertion order: oldest first
  }

  get(key) {
    if (!this.map.has(key)) return undefined; // miss
    const value = this.map.get(key);
    this.map.delete(key); // move key to the most-recent end
    this.map.set(key, value);
    return value; // hit
  }

  set(key, value) {
    if (this.map.has(key)) this.map.delete(key);
    else if (this.map.size === this.capacity) {
      const oldest = this.map.keys().next().value;
      this.map.delete(oldest); // evict the least recently used key
    }
    this.map.set(key, value);
  }
}

const cache = new LRUCache(3);

// cache-aside (lazy loading): the application talks to both cache and DB
async function getProduct(id, db) {
  const cached = cache.get(id);
  if (cached !== undefined) return cached; // cache hit
  const product = await db.findProduct(id); // cache miss -> read the DB
  cache.set(id, product); // populate so the next read is a hit
  return product;
}

from collections import OrderedDict


class LRUCache:
    def __init__(self, capacity: int):
        self.capacity = capacity
        self.data = OrderedDict()  # oldest first

    def get(self, key):
        if key not in self.data:
            return None  # miss
        self.data.move_to_end(key)  # mark as most recently used
        return self.data[key]  # hit

    def set(self, key, value):
        if key in self.data:
            self.data.move_to_end(key)
        elif len(self.data) == self.capacity:
            self.data.popitem(last=False)  # evict the least recently used
        self.data[key] = value


