import java.util.LinkedHashMap;
import java.util.Map;

class LRUCache<K, V> extends LinkedHashMap<K, V> {
    private final int capacity;

    LRUCache(int capacity) {
        super(16, 0.75f, true); // accessOrder = true: get() moves the entry to the end
        this.capacity = capacity;
    }

    @Override
    protected boolean removeEldestEntry(Map.Entry<K, V> eldest) {
        return size() > capacity; // evict the least recently used entry
    }
}

class ProductService {
    private final LRUCache<Long, String> cache = new LRUCache<>(3);
    private final ProductRepository db;

    ProductService(ProductRepository db) {
        this.db = db;
    }

    String getProduct(long id) { // cache-aside read
        String cached = cache.get(id);
        if (cached != null) return cached; // cache hit
        String product = db.findProduct(id); // cache miss -> read the DB
        cache.put(id, product);
        return product;
    }
}

interface ProductRepository {
    String findProduct(long id);
}

