const { createHash } = require('node:crypto');

// 32-bit ring position = first 4 bytes of MD5 (ketama-style; used for spread, not security)
function hash32(str) {
  return createHash('md5').update(str).digest().readUInt32BE(0);
}

class HashRing {
  constructor(vnodes = 100) {
    this.vnodes = vnodes; // virtual nodes per server smooth out the load
    this.ring = [];       // [position, server] pairs sorted by position
  }

  addServer(server) {
    for (let v = 0; v < this.vnodes; v++) {
      this.ring.push([hash32(`${server}#${v}`), server]);
    }
    this.ring.sort((a, b) => a[0] - b[0]);
  }

  removeServer(server) {
    this.ring = this.ring.filter(([, s]) => s !== server);
  }

  getServer(key) {
    const h = hash32(key);
    let lo = 0, hi = this.ring.length; // binary search: first position >= h
    while (lo < hi) {
      const mid = (lo + hi) >> 1;
      if (this.ring[mid][0] < h) lo = mid + 1;
      else hi = mid;
    }
    return this.ring[lo % this.ring.length][1]; // past the end -> wrap to the start
  }
}

import bisect
import hashlib


def hash32(s: str) -> int:
    """32-bit ring position = first 4 bytes of MD5 (for spread, not security)."""
    return int.from_bytes(hashlib.md5(s.encode()).digest()[:4], "big")


class HashRing:
    def __init__(self, vnodes: int = 100):
        self.vnodes = vnodes
        self.positions: list[int] = []  # sorted ring positions
        self.owner: dict[int, str] = {}  # position -> server

    def add_server(self, server: str) -> None:
        for v in range(self.vnodes):
            pos = hash32(f"{server}#{v}")
            bisect.insort(self.positions, pos)
            self.owner[pos] = server

    def remove_server(self, server: str) -> None:
        self.positions = [p for p in self.positions if self.owner[p] != server]
        self.owner = {p: s for p, s in self.owner.items() if s != server}

    def get_server(self, key: str) -> str:
        i = bisect.bisect_left(self.positions, hash32(key))  # first position >= hash
        return self.owner[self.positions[i % len(self.positions)]]  # wrap around

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.Map;
import java.util.TreeMap;

class HashRing {
    private final int vnodes;
    private final TreeMap<Long, String> ring = new TreeMap<>(); // position -> server

    HashRing(int vnodes) {
        this.vnodes = vnodes;
    }

    // 32-bit ring position = first 4 bytes of MD5 (for spread, not security)
    static long hash32(String s) {
        try {
            byte[] d = MessageDigest.getInstance("MD5").digest(s.getBytes(StandardCharsets.UTF_8));
            return ((d[0] & 0xFFL) << 24) | ((d[1] & 0xFFL) << 16) | ((d[2] & 0xFFL) << 8) | (d[3] & 0xFFL);
        } catch (NoSuchAlgorithmException e) {
            throw new IllegalStateException(e);
        }
    }

    void addServer(String server) {
        for (int v = 0; v < vnodes; v++) ring.put(hash32(server + "#" + v), server);
    }

    void removeServer(String server) {
        ring.values().removeIf(s -> s.equals(server));
    }

    String getServer(String key) {
        Map.Entry<Long, String> e = ring.ceilingEntry(hash32(key)); // first position >= hash
        return (e != null ? e : ring.firstEntry()).getValue();       // wrap around
    }
}

// Worker loop: at-least-once delivery, retries with backoff, dead-letter queue
async function consume(queue, handler, maxAttempts = 3) {
  for await (const msg of queue) {
    try {
      await handler(msg.body);
      await queue.ack(msg); // success: delete the message
    } catch (err) {
      msg.attempts += 1;
      if (msg.attempts >= maxAttempts) {
        await queue.deadLetter(msg, err); // park it for a human to inspect
      } else {
        await queue.retryLater(msg, 1000 * 2 ** msg.attempts); // exponential backoff
      }
    }
  }
}

// Idempotent handler: the same event may arrive twice, the effect happens once
async function onPaymentCaptured(event, db) {
  await db.transaction(async (tx) => {
    const firstTime = await tx.insertIfAbsent('processed_events', event.eventId);
    if (!firstTime) return; // duplicate delivery: skip
    await tx.update('orders', event.orderId, { status: 'PAID' });
  });
}

const ALPHABET = '0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ';

// Turn a unique numeric id (from a counter / ID service) into a short code.
function encodeBase62(id) {
  if (id === 0) return ALPHABET[0];
  const digits = [];
  while (id > 0) {
    const rem = id % 62;
    digits.push(ALPHABET[rem]);
    id = Math.floor(id / 62);
  }
  return digits.reverse().join('');
}

// Reverse: short code -> id (useful if rows are keyed by the numeric id).
function decodeBase62(code) {
  let id = 0;
  for (const ch of code) {
    const digit = ALPHABET.indexOf(ch);
    if (digit === -1) throw new Error(`invalid character: ${ch}`); // -> 404
    id = id * 62 + digit;
  }
  return id;
}

