class TokenBucket {
  // capacity = max burst, refillPerSec = sustained rate
  constructor(capacity, refillPerSec, now = performance.now() / 1000) {
    this.capacity = capacity;
    this.refillPerSec = refillPerSec;
    this.tokens = capacity; // start full
    this.last = now;        // time of the last refill, in seconds
  }

  tryAcquire(now = performance.now() / 1000) {
    const elapsed = now - this.last;
    this.tokens = Math.min(this.capacity, this.tokens + elapsed * this.refillPerSec);
    this.last = now;
    if (this.tokens >= 1) {
      this.tokens -= 1;
      return true; // allow the request
    }
    return false; // reject: respond 429 Too Many Requests
  }
}

// one bucket per client (user id, API key or IP)
const buckets = new Map();

function allowRequest(clientId) {
  if (!buckets.has(clientId)) buckets.set(clientId, new TokenBucket(3, 1));
  return buckets.get(clientId).tryAcquire();
}

class TokenBucket {
    private final int capacity;        // max burst
    private final double refillPerSec; // sustained rate
    private double tokens;
    private long lastNanos;

    TokenBucket(int capacity, double refillPerSec, long nowNanos) {
        this.capacity = capacity;
        this.refillPerSec = refillPerSec;
        this.tokens = capacity; // start full
        this.lastNanos = nowNanos;
    }

    TokenBucket(int capacity, double refillPerSec) {
        this(capacity, refillPerSec, System.nanoTime());
    }

    synchronized boolean tryAcquire() {
        return tryAcquire(System.nanoTime());
    }

    synchronized boolean tryAcquire(long nowNanos) {
        double elapsedSec = (nowNanos - lastNanos) / 1e9;
        tokens = Math.min(capacity, tokens + elapsedSec * refillPerSec);
        lastNanos = nowNanos;
        if (tokens >= 1) {
            tokens -= 1;
            return true;  // allow the request
        }
        return false;     // reject: respond 429 Too Many Requests
    }
}
